package com.paymentplatform.reconciliation_service.domain;
import com.paymentplatform.reconciliation_service.api.ApiException;import com.paymentplatform.reconciliation_service.client.DependencyClient;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import tools.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import java.math.BigInteger;
@Service public class ExternalStatementService {
 private final String tokens;private final org.springframework.security.oauth2.jwt.JwtDecoder decoder;private final JdbcTemplate jdbc;private final DependencyClient client;private final ObjectMapper json;
 public ExternalStatementService(JdbcTemplate jdbc,DependencyClient client,ObjectMapper json,@org.springframework.beans.factory.annotation.Value("${boodoo.statements.tokens-json:{}}") String tokens,org.springframework.security.oauth2.jwt.JwtDecoder decoder){this.tokens=tokens;this.decoder=decoder;this.jdbc=jdbc;this.client=client;this.json=json;}
 public record Line(@NotBlank @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9._:-]{0,127}") String externalId,@NotNull UUID reference,@NotBlank @Pattern(regexp="DEBIT|CREDIT") String side,@NotNull @Positive Long amount){}
 public record Request(@NotNull UUID id,@NotNull UUID accountId,@NotBlank @Pattern(regexp="[A-Z][A-Z0-9_-]{0,63}") String provider,@NotBlank @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9._:-]{0,127}") String statementReference,@NotNull Instant from,@NotNull Instant to,@NotNull @Min(0) Long opening,@NotNull @Min(0) Long closing,@NotNull @Size(max=500) List<@NotNull @Valid Line> entries){}
 public record Report(UUID id,UUID accountId,String provider,String statementReference,String status,long unmatchedExternal,long unmatchedLedger,long ledgerOpening,long ledgerClosing,Instant checkedAt){}
 private String hash(String actor,Request r){return RequestKeys.hash(json.writeValueAsString(r),actor);}
 public Report get(String tenant,UUID id){return jdbc.query("SELECT snapshot::text FROM external_statements WHERE integrator_id=? AND id=?",(r,n)->json.readValue(r.getString(1),Report.class),tenant,id).stream().findFirst().orElseThrow(()->error(HttpStatus.NOT_FOUND,"STATEMENT_NOT_FOUND"));}
 public Report reconcile(String tenant,String actor,Request request,String bearer){
  if(!request.from().isBefore(request.to())||Duration.between(request.from(),request.to()).compareTo(Duration.ofDays(31))>0||request.to().isAfter(Instant.now().minusSeconds(60))||request.entries().stream().map(Line::externalId).distinct().count()!=request.entries().size()||request.entries().stream().map(Line::reference).distinct().count()!=request.entries().size())throw error(HttpStatus.BAD_REQUEST,"INVALID_STATEMENT");
  BigInteger calculated=BigInteger.valueOf(request.opening());for(var line:request.entries())calculated=calculated.add(BigInteger.valueOf(line.amount()).multiply(BigInteger.valueOf(line.side().equals("DEBIT")?1:-1)));if(!calculated.equals(BigInteger.valueOf(request.closing())))throw error(HttpStatus.BAD_REQUEST,"STATEMENT_ARITHMETIC_MISMATCH");
  String hash=hash(actor,request);var previous=jdbc.query("SELECT fingerprint FROM external_statements WHERE integrator_id=? AND id=?",(r,n)->r.getString(1),tenant,request.id());if(!previous.isEmpty()){if(!previous.getFirst().equals(hash))throw error(HttpStatus.CONFLICT,"STATEMENT_ID_CONFLICT");return get(tenant,request.id());}
  var result=client.get("ledger","/internal/v1/accounts/"+request.accountId()+"/statement?from="+request.from()+"&to="+request.to(),bearer);if(result.status()!=200)throw DependencyClient.unavailable();var b=result.body();
  if(!request.accountId().equals(DependencyClient.uuid(b,"accountId"))||!"XOF".equals(DependencyClient.text(b,"currency"))||!request.from().equals(Instant.parse(DependencyClient.text(b,"from")))||!request.to().equals(Instant.parse(DependencyClient.text(b,"to"))))throw DependencyClient.unavailable();
  Instant checked=Instant.parse(DependencyClient.text(b,"checkedAt"));if(checked.isBefore(Instant.now().minusSeconds(60))||checked.isAfter(Instant.now().plusSeconds(30)))throw DependencyClient.unavailable();
  var entries=b.get("entries");long count=DependencyClient.integer(b,"entryCount");if(count<0||entries==null||!entries.isArray()||entries.size()>500||entries.size()>count)throw DependencyClient.unavailable();
  Set<String> bank=new HashSet<>(),ledger=new HashSet<>();for(var line:request.entries())bank.add(line.reference()+":"+line.side()+":"+line.amount());
  for(var line:entries){String side=DependencyClient.text(line,"side");long amount=DependencyClient.integer(line,"amount");if(!Set.of("DEBIT","CREDIT").contains(side)||amount<=0||!ledger.add(DependencyClient.uuid(line,"reference")+":"+side+":"+amount))throw DependencyClient.unavailable();}
  long unmatchedExternal=bank.stream().filter(e->!ledger.contains(e)).count(),unmatchedLedger=ledger.stream().filter(e->!bank.contains(e)).count();long opening=DependencyClient.integer(b,"opening"),closing=DependencyClient.integer(b,"closing");boolean complete=DependencyClient.bool(b,"complete")&&count==entries.size();
  String status=!complete?"INCOMPLETE":unmatchedExternal==0&&unmatchedLedger==0&&opening==request.opening()&&closing==request.closing()?"MATCHED":"DISCREPANCY";
  var report=new Report(request.id(),request.accountId(),request.provider(),request.statementReference(),status,unmatchedExternal,unmatchedLedger,opening,closing,checked);
  int inserted=jdbc.update("INSERT INTO external_statements(integrator_id,id,provider,statement_reference,fingerprint,source,snapshot) VALUES (?,?,?,?,?,?::jsonb,?::jsonb) ON CONFLICT DO NOTHING",tenant,request.id(),request.provider(),request.statementReference(),hash,json.writeValueAsString(request),json.writeValueAsString(report));
  if(inserted==0){var saved=jdbc.query("SELECT fingerprint FROM external_statements WHERE integrator_id=? AND id=?",(r,n)->r.getString(1),tenant,request.id());if(saved.isEmpty()||!saved.getFirst().equals(hash))throw error(HttpStatus.CONFLICT,"STATEMENT_IDENTITY_CONFLICT");return get(tenant,request.id());}return report;
 }
 public record Note(UUID id,String actor,String reasonCode,UUID relatedJournalId,Instant createdAt){}
 public List<Note> notes(String tenant,UUID report,UUID after,int limit){get(tenant,report);return jdbc.query("SELECT * FROM statement_investigations WHERE integrator_id=? AND report_id=? AND (?::uuid IS NULL OR id>?::uuid) ORDER BY id LIMIT ?",(r,n)->new Note(r.getObject("id",UUID.class),r.getString("actor_id"),r.getString("reason_code"),r.getObject("related_journal_id",UUID.class),r.getObject("created_at",OffsetDateTime.class).toInstant()),tenant,report,after,after,limit);}
 public record Investigation(@NotNull UUID id,@NotBlank @Pattern(regexp="[A-Z][A-Z0-9_]{0,63}") String reasonCode,@NotNull UUID relatedJournalId){}
 public void investigate(String tenant,String actor,UUID report,Investigation request,String ignoredCallerToken){get(tenant,report);String bearer;try{bearer=DependencyClient.text(json.readTree(tokens),tenant);var jwt=decoder.decode(bearer);if(!tenant.equals(jwt.getClaimAsString("integrator_id"))||!"service".equals(jwt.getClaims().get("actor_type"))||!"reconciliation-service".equals(jwt.getSubject()))throw DependencyClient.unavailable();}catch(Exception e){throw DependencyClient.unavailable();}var journal=client.get("ledger","/internal/v1/journals/"+request.relatedJournalId(),bearer);if(journal.status()!=200||!request.relatedJournalId().equals(DependencyClient.uuid(journal.body(),"id")))throw DependencyClient.unavailable();String hash=RequestKeys.hash(json.writeValueAsString(List.of(report,request)),actor);int inserted=jdbc.update("INSERT INTO statement_investigations(integrator_id,id,report_id,actor_id,reason_code,fingerprint,related_journal_id) VALUES (?,?,?,?,?,?,?) ON CONFLICT DO NOTHING",tenant,request.id(),report,actor,request.reasonCode(),hash,request.relatedJournalId());if(inserted==0){String old=jdbc.queryForObject("SELECT fingerprint FROM statement_investigations WHERE integrator_id=? AND id=?",String.class,tenant,request.id());if(!hash.equals(old))throw error(HttpStatus.CONFLICT,"INVESTIGATION_ID_CONFLICT");}}
 private ApiException error(HttpStatus s,String c){return new ApiException(s,c,"The external statement operation cannot be accepted.");}
}
